9424:function Enter-TaskLock {
9425:    param([string]$TaskDir, [string]$Task, [string]$Panel = '')
9426:    $path = Join-Path $TaskDir '.consult.lock'
9427:    $share = if ($script:OnWindows) { [IO.FileShare]::Read } else { [IO.FileShare]::None }
9428:    $record = [pscustomobject]@{
9429:        pid        = $PID
9430:        start_time = (Get-ProcessStartIso -ProcessId $PID)
9431:        host       = [Environment]::MachineName
9432:        task       = $Task
9433:        started    = (Get-IsoTimestamp)
9434:    }
9435:    if ($Panel) { $record | Add-Member -NotePropertyName 'panel' -NotePropertyValue $Panel }
9436:    $fs = $null
9437:    try {
9438:        $fs = [IO.File]::Open($path, [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, $share)
9439:    } catch [System.IO.IOException] {
9440:        # The holder may not have replaced its predecessor's informational record
9441:        # yet: re-read briefly and name a pid only when that pid is alive.
9442:        $holder = $null
9443:        for ($attempt = 1; $attempt -le 8; $attempt++) {
9444:            $candidate = Read-LockContent -Path $path
9445:            $cpid = 0
9446:            if ($candidate -and [int]::TryParse([string](Get-PropertyValue $candidate 'pid' ''), [ref]$cpid) -and
9447:                (Test-PidAlive -ProcessId $cpid -StartTime (ConvertTo-JsonText (Get-PropertyValue $candidate 'start_time' '')))) { $holder = $candidate; break }
9448:            Start-Sleep -Milliseconds 125
9449:        }
9450:        $who = 'a live process'
9451:        if ($holder) {
9452:            $who = "pid $(Get-PropertyValue $holder 'pid' '?') on $(Get-PropertyValue $holder 'host' '?') since $(Get-PropertyValue $holder 'started' '?')"
9453:            $holderPanel = [string](Get-PropertyValue $holder 'panel' '')
9454:            if ($holderPanel) { $who += " (review panel $($holderPanel.Substring(0, [Math]::Min(8, $holderPanel.Length))))" }
9455:        }
9456:        return (New-LockRefusal -Path $path -Message "another consultation or status update for task '$Task' is running: $path is held open by $who. Wait for it to finish; the lock is released when that process exits.")
9457:    } catch {
9458:        return (New-LockRefusal -Path $path -Message "could not open the lock '$path': $($_.Exception.Message)")
9459:    }
9460:    # Informational only (who holds it); nothing recoverable lives here.
9461:    try {
9462:        $bytes = $script:Utf8NoBom.GetBytes((ConvertTo-Json -InputObject $record -Compress) + "`n")
9463:        $fs.SetLength(0)
9464:        $fs.Position = 0
9465:        $fs.Write($bytes, 0, $bytes.Length)
9466:        $fs.Flush($true)
9467:    } catch { }
9468:    return [pscustomobject]@{ Acquired = $true; Path = $path; Stream = $fs; Record = $record; Message = '' }
9469:}
