2509:
2510:# (wave 28, R17) the first run after an install - a real run the coordinator started, or the
2511:# foreground of -Detach; never a dry run, a panel member or a detached background - prints the
2512:# telemetry notice once (telemetry on only; the marker <codex home>/telemetry-notice-<version>)
2513:if ((-not $DryRun -or $detachForeground) -and -not $panelMember -and -not $script:DetachRun) { Show-TelemetryNotice -Switch $telemetrySwitch }
2514:
2515:# ----------------------------------------------------------------------------- review panel (-Panel)
2516:#
2517:# The roster is walked like the single-reviewer walk, without stopping at the first available
2518:# entry (Select-PanelMembers). Each member then runs as a complete consultation of its own - a
2519:# child run of this script (-PanelSpec) in a process of its own: own preflight, own recovery
2520:# record .consult.pending-<NN>.json, own parent thread (the newest of its lineage, or a new one;
2521:# -Mode new: new for all), own consultation id, handoff files
2522:# handoffs/NN-<engine>-<ReplyName>-<provider>.md and ledger entry with the `panel` record.
2523:# 0.4.x wave 21 (ROADMAP R11) - the members run IN PARALLEL; this run:
2524:#   1. takes the task lock (.consult.lock; its informational record names the panel) and holds
2525:#      it until the summary is printed: no other consultation or status update of the task in
---
2530:#      the roster order unless the panel is routed; member k: n0 + k - 1, NN0 + k - 1), so the
2531:#      files and the ledger keep that order whatever finishes first;
2532:#   4. writes every member's `reserved` record (the panel, n, NN, this process as writer and
2533:#      parent) BEFORE it launches any member - a member proves its parent with it, rewrites it
2534:#      with its own pid and only then checks that the parent lives (D6, D1, F07-1);
2535:#   5. launches the members as processes of their own (Start-Process; console output to files
2536:#      in a temp directory) along the plan of Get-PanelPlan - members of different endpoints at
2537:#      once, of one endpoint one after another unless the roster's "parallel" raises it,
2538:#      -PanelConcurrency caps the total (D8) - polls them, prints one line per finished member
2539:#      and stops a member that outlives its guard (its timeout + its format-repair and
2540:#      denial-retry budgets + (wave 24) its timeout continuation's -ContinueSec + 60 s write
2541:#      lock + 120 s, D11; Get-PanelMemberGuard);
2542:#   6. prints every member's console output in roster order, the summary with the panel's wall
2543:#      clock, and removes the records of members that never started anything (D5).
2544:# A member that fails or is refused does not stop the others; with -PanelConcurrency 1 a member
2545:# that leaves surviving processes stops the rest (recorded as skipped, exit 1; F15-3). Exit 0
2546:# only when every member produced a usable reply (-DryRun: when every member's plan could be
2547:# made; a dry run writes nothing and takes no lock).
2548:
2549:# The ledger entry a panel member recorded (the task's sessions.json, read tolerantly).
2550:function Find-PanelEntry {
2551:    param([string]$Path, [string]$PanelId, [int]$Position)
2552:    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
2553:    $data = $null
2554:    try { $data = ConvertFrom-Json -InputObject (Read-SharedText -Path $Path) } catch { return $null }
2555:    $found = $null
2556:    foreach ($c in @(Get-PropertyValue (Get-PropertyValue $data 'codex' $null) 'consults' @())) {
2557:        $pr = Get-PropertyValue $c 'panel' $null
2558:        if ($null -ne $pr -and [string](Get-PropertyValue $pr 'id' '') -eq $PanelId -and [string](Get-PropertyValue $pr 'position' '') -eq [string]$Position) { $found = $c }
2559:    }
2560:    return $found
2561:}
2562:
2563:function Format-PriorCounts {
2564:    param($Entry)
2565:    $prior = @(Get-PropertyValue $Entry 'prior_findings' @() | Where-Object { $_ })
2566:    if ($prior.Count -eq 0) { return 'prior: none' }
2567:    $parts = New-Object System.Collections.Generic.List[string]
2568:    foreach ($st in $script:PriorStatuses) {
2569:        $n = @($prior | Where-Object { [string](Get-PropertyValue $_ 'status' '') -eq $st }).Count
2570:        if ($n -gt 0) { $parts.Add("$n $st") }
2571:    }
2572:    return 'prior: ' + ($parts.ToArray() -join ', ')
2573:}
2574:
2575:# The console output of a member (its stdout, then its stderr file; UTF-8) as lines.
2576:function Read-PanelMemberOutput {
2577:    param($Slot)
2578:    $lines = New-Object System.Collections.Generic.List[string]
2579:    foreach ($f in @($Slot.OutPath, $Slot.ErrPath)) {
2580:        if (-not $f) { continue }
2581:        $t = Read-SharedText -Path $f
2582:        if (-not $t -or -not $t.Trim()) { continue }
2583:        foreach ($l in ($t.TrimEnd() -split "`r?`n")) { $lines.Add($l) }
2584:    }
2585:    return , ([string[]]$lines.ToArray())
2586:}
