2588:# Starts one member: its spec (base64 of UTF-8 JSON on the command line, as before), its console
2589:# output to <temp>/codex-consult-panel-<id>/<NN>.out|.err, stdin from an empty file. Reads the
2590:# panel run's variables; sets the slot's Proc / Watch / State ('running' | 'failed-start').
2591:function Start-PanelMember {
2592:    param($Slot)
2593:    $pm = $Slot.Pm
2594:    # The members whose files this member's agy tree check leaves out (D7): deliberately the
2595:    # UNION of all other slots whenever the plan lets any two members run at once - not only
2596:    # those the scheduler can actually run beside this one (F11-5). That costs no evidence: an
2597:    # ignored path that did not change hides nothing, and one that changed was written by a
2598:    # member running meanwhile (or by this member's own reviewer - the D7 residual the README
2599:    # names: the ignored paths are the task's stores and the other members' handoff names).
2600:    $siblings = @()
2601:    if ($panelPlan.Effective -gt 1) { $siblings = @($panelSlots | Where-Object { $_.K -ne $Slot.K } | ForEach-Object { [string]$_.Nn }) }
2602:    $spec = [pscustomobject]@{
2603:        id                = $panelId
2604:        position          = $Slot.K
2605:        of                = $panelRunners.Count
2606:        members           = $panelMembersRecord
2607:        roster_position   = $pm.Entry.Position
2608:        provider          = $pm.Entry.Provider
2609:        model             = $pm.Entry.Model
2610:        engine            = [string]$pm.Entry.Engine
2611:        skipped           = $panelSkippedRecord
2612:        listed_ids        = [object[]]$panelListed
2613:        n                 = $Slot.N
2614:        nn                = $Slot.Nn
2615:        consult_id        = $Slot.ConsultId
2616:        parent_pid        = $PID
2617:        parent_start_time = $panelParentStart
2618:        sibling_nns       = [object[]]$siblings
2619:        concurrency       = $panelPlan.Effective
2620:        limits            = $panelLimits
2621:        asked             = $panelRoute.SizeAsked
2622:        routing           = $panelRoute.Routing
2623:        role              = $(if ($panelRoleOf.ContainsKey([int]$pm.Entry.Position)) { [string]$panelRoleOf[[int]$pm.Entry.Position] } else { '' })
2624:        roles_note        = $panelRolesNote
2625:        panel_warnings    = [object[]]@($panelWarnings)
2626:        # (wave 27, R13) the coordinator the panel run resolved, and the host markers of its
2627:        # environment - the member never resolves them again
2628:        coordinator        = $coordinatorRecord
2629:        child_env_scrubbed = [object[]]@($childEnvScrubbed)
2630:        args              = [pscustomobject]@{
2631:            collab_dir       = $CollabDir
2632:            mode             = $Mode
2633:            brief            = $Brief
2634:            prompt           = $Prompt
2635:            purpose          = $Purpose
2636:            effort           = $Effort
2637:            sandbox          = $Sandbox
2638:            max_words        = $MaxWords
2639:            timeout_sec      = $Slot.TimeoutSec
2640:            timeout_source   = $Slot.TimeoutSource
2641:            continue_sec     = $Slot.ContinueSec
2642:            stall_sec        = $Slot.StallSec
2643:            range            = $Range
2644:            range_stat       = $rangeRecord
2645:            reply_name       = $Slot.ReplyName
2646:            artifact         = [object[]]@($Artifact)
2647:            raw              = [bool]$Raw
2648:            codex_exe        = $CodexExe
2649:            native_effort    = $NativeEffort
2650:            off_peak_only    = [bool]$OffPeakOnly
2651:            skip_preflight   = [bool]$SkipPreflight
2652:            codex_config     = [object[]]@($CodexConfig)
2653:            schema_transport = $transportOverride
2654:            format_retry     = $FormatRetry
2655:            engine           = $Engine
2656:            engine_exe       = $EngineExe
2657:            denial_retry     = $DenialRetry
2658:            max_model_steps  = $MaxModelSteps
2659:            topics           = [object[]]@($topicList)
2660:            brief_prefix     = $BriefPrefix
2661:            telemetry        = $telemetrySwitch.Text
2662:            dry_run          = [bool]$DryRun
2663:        }
2664:    }
2665:    $specB64 = [Convert]::ToBase64String($script:Utf8NoBom.GetBytes((ConvertTo-Json -InputObject $spec -Depth 8 -Compress)))
2666:    $Slot.OutPath = Join-Path $panelTmp "$($Slot.Nn).out"
2667:    $Slot.ErrPath = Join-Path $panelTmp "$($Slot.Nn).err"
2668:    $argLine = (@('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $panelSelf, '-Task', $Task, '-PanelSpec', $specB64) | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' '
2669:    try {
2670:        $Slot.Proc = Start-Process -FilePath $panelHost -ArgumentList $argLine -WorkingDirectory $callerCwd -NoNewWindow -PassThru `
2671:            -RedirectStandardOutput $Slot.OutPath -RedirectStandardError $Slot.ErrPath -RedirectStandardInput $panelEmptyIn
2672:        # PS 5.1: touch .Handle right away, or .ExitCode comes back empty (see the run below)
2673:        if ($script:LegacyPS) { try { $null = $Slot.Proc.Handle } catch { } }
2674:        $Slot.Watch = [System.Diagnostics.Stopwatch]::StartNew()
2675:        $Slot.State = 'running'
2676:    } catch {
2677:        $Slot.State = 'failed-start'
2678:        $Slot.StartError = ConvertTo-OneLine $_.Exception.Message
2679:    }
2680:}
