2682:# A finished (or stopped) member: its console output, its refusal line, its ledger entry and
2683:# what became of its recovery record.
2684:function Complete-PanelMember {
2685:    param($Slot)
2686:    $Slot.Lines = Read-PanelMemberOutput $Slot
2687:    $last = @($Slot.Lines | Where-Object { $_ -match '^codex-consult: ' }) | Select-Object -Last 1
2688:    $Slot.Refusal = $(if ($last) { $last -replace '^codex-consult: ', '' } else { "exit $($Slot.Exit)" })
2689:    if (-not $DryRun) {
2690:        $Slot.Entry = Find-PanelEntry -Path $sessionsPath -PanelId $panelId -Position $Slot.K
2691:        $rd = Read-PendingFile -Path $Slot.RecordPath
2692:        $Slot.RecordState = $(if ($rd.Exists -and $rd.Record) { [string](Get-PropertyValue $rd.Record 'state' '') } else { '' })
2693:    }
2694:}
2695:
2696:# One phrase for a member that ran (the progress line; the summary builds on it).
2697:function Get-PanelMemberStatus {
2698:    param($Slot)
2699:    if ($Slot.State -eq 'killed') { return "killed by the panel after $($Slot.Wall) s (its guard: $($Slot.Guard) s)" }
2700:    if ($Slot.State -eq 'failed-start') { return "failed: could not start the member process - $($Slot.StartError)" }
2701:    if ($DryRun) { if ($Slot.Exit -eq 0) { return 'planned' } else { return "refused: $(ConvertTo-OneLine $Slot.Refusal)" } }
2702:    if ($null -ne $Slot.Entry) { return [string](Get-PropertyValue $Slot.Entry 'bridge_outcome' '') }
2703:    if ($Slot.RecordState -eq 'committing') {
2704:        # D3: the write lock never acquired (the member says so) - or stopped INSIDE its commit
2705:        # (a kill, a crash: its findings may be ORPHAN; the record names the kept reply)
2706:        if ($Slot.Refusal -match '^commit blocked:') { return "commit blocked: $(ConvertTo-OneLine ($Slot.Refusal -replace '^commit blocked:\s*', ''))" }
2707:        return "failed: stopped inside its commit (exit $($Slot.Exit)); findings it wrote have no ledger entry (ORPHAN)"
2708:    }
2709:    return "failed: $(ConvertTo-OneLine $Slot.Refusal)"
2710:}
2711:
2712:# (wave 26) Did a member produce a usable reply (it ran, was not killed, its ledger entry says so)?
2713:function Test-PanelSlotUsable {
2714:    param($Slot)
2715:    if ($Slot.State -ne 'done' -or $null -eq $Slot.Entry) { return $false }
2716:    return (Test-UsableOutcome ([string](Get-PropertyValue $Slot.Entry 'bridge_outcome' '')))
2717:}
2718:
2719:# (wave 25, D11) A member's state in a detached panel's status file - the classes behind
2720:# Get-PanelMemberStatus: pending | running | usable | failed | killed | blocked | commit_blocked |
2721:# orphan (a roster-skipped entry is `skipped` from the start; a member never started, at the end).
2722:function Get-PanelSlotDetachState {
2723:    param($Slot)
2724:    switch ($Slot.State) {
2725:        'waiting' { return 'pending' }
---
2840:    $panelMembersRecord = [object[]]@($panelEntries | ForEach-Object { [pscustomobject]@{ provider = $_.Entry.Provider; model = $_.Identity.Model; state = $_.State; reason = $_.Reason } })
2841:    # (wave 26, D6) an entry that is eligible but got no seat ('not-picked') is no skip
2842:    $panelSkippedRecord = [object[]]@($panelEntries | Where-Object { $_.State -eq 'skipped' } | ForEach-Object { [pscustomobject]@{ provider = $_.Entry.Provider; model = $_.Identity.Model; engine = [string]$_.Entry.Engine; reason = $_.Reason } })
2843:    # The plan (D8): endpoint groups, the roster's "parallel", -PanelConcurrency.
2844:    $panelPlan = Get-PanelPlan -Runners $panelRunners -Parallel $roster.Parallel -Cap $PanelConcurrency
2845:    $panelLimits = [pscustomobject]$panelPlan.Limits
2846:    $panelParentStart = [string](Get-ProcessStartIso -ProcessId $PID)
2847:    $panelSelf = $PSCommandPath
2848:    $panelHost = (Get-Process -Id $PID).Path
2849:    $panelTmp = Join-Path ([IO.Path]::GetTempPath()) "codex-consult-panel-$panelId"
2850:    $panelEmptyIn = Join-Path $panelTmp 'stdin.empty'
2851:    $panelLock = $null
2852:    $panelSlots = New-Object System.Collections.Generic.List[object]
2853:    $panelWatch = [System.Diagnostics.Stopwatch]::StartNew()
2854:    try {
2855:        if (-not $DryRun) {
2856:            [void][IO.Directory]::CreateDirectory($handoffsDir)
2857:            $panelLock = Enter-TaskLock -TaskDir $taskDir -Task $Task -Panel $panelId
2858:            if (-not $panelLock.Acquired) { Stop-WithError $panelLock.Message }
2859:        }
2860:        # Every recovery record of the task, judged before anything is written: an active one
2861:        # refuses the panel (a dry run reports it); the others are consumed below.
2862:        $panelPending = Read-TaskPendingRecords -TaskDir $taskDir
2863:        if ($panelPending.Error) { Stop-WithError $panelPending.Error }
2864:        $panelPendingRefusal = ''
2865:        if ($panelPending.Active) {
2866:            if ($DryRun -and -not $detachForeground) { $panelPendingRefusal = [string]$panelPending.Active.Check.Message } else { Stop-WithError $panelPending.Active.Check.Message }
2867:        }
2868:        # The numbers of every member, past everything on disk (a store that does not parse
2869:        # refuses here, before any member starts).
2870:        $panelSessions = Read-JsonStore -Path $sessionsPath
2871:        $panelConsults = @()
2872:        if ($null -ne $panelSessions) { $panelConsults = @(Get-PropertyValue (Get-PropertyValue $panelSessions 'codex' $null) 'consults' @() | Where-Object { $_ }) }
2873:        $panelStore = Read-FindingsFile -Path $findingsPath -Task $Task
2874:        $panelNumbers = Get-NextNumbers -Consults $panelConsults -Store $panelStore -HandoffsDir $handoffsDir -Leftovers @($panelPending.Items | ForEach-Object { $_.Record })
2875:        # The findings every member is shown: those open when the panel starts.
2876:        $panelListed = @()
2877:        if (-not $Raw) {
2878:            $panelListed = @(@($panelStore.findings) | Where-Object { $_ -and $script:OpenStatuses -contains [string](Get-PropertyValue $_ 'status' '') } | ForEach-Object { [string]$_.id })
2879:        }
2880:        $guardHook = 0
2881:        [void][int]::TryParse((Get-TestHookValue 'CODEX_CONSULT_TEST_PANEL_GUARD_SEC'), [ref]$guardHook)
2882:        $slotOf = @{}
2883:        $k = 0
2884:        foreach ($pm in $panelRunners) {
2885:            $k++
2886:            $slug = ($pm.Entry.Provider.ToLowerInvariant() -replace '[^a-z0-9._-]', '-').Trim('-')
2887:            if (-not $slug) { $slug = 'reviewer' }
2888:            $engineK = [string]$pm.Entry.Engine
2889:            if (-not $engineK) { $engineK = 'codex' }
2890:            $nnK = '{0:D2}' -f ([int]$panelNumbers.Nn + $k - 1)
2891:            # The kill guard from the member's own budgets (D11, Get-PanelMemberGuard): its
2892:            # timeout, one format-repair turn and (an engine with a denial retry: agy) one
2893:            # denial-retry turn of min(timeout, 300) s when enabled, (wave 24) the timeout
2894:            # continuation's -ContinueSec, the 60 s write-lock wait, 120 s slack. TEST HOOK:
2895:            # CODEX_CONSULT_TEST_PANEL_GUARD_SEC.
2896:            # (wave 26b, D11) the roster entry's own timeout_sec replaces the purpose default for
2897:            # this member (an explicit -TimeoutSec wins for all); its continuation budget follows
2898:            # it unless -ContinueSec was given
2899:            $slotTimeout = $TimeoutSec
2900:            $slotTimeoutSource = $timeoutSource
2901:            $slotContinue = $ContinueSec
2902:            $entryTimeout = [int](Get-PropertyValue $pm.Entry 'TimeoutSec' 0)
2903:            if ($timeoutSource -ne 'explicit' -and $entryTimeout -gt 0) {
2904:                $slotTimeout = $entryTimeout
2905:                $slotTimeoutSource = 'roster'
2906:                if (-not $continueGiven) { $slotContinue = [Math]::Min($entryTimeout, 900) }
2907:            }
2908:            # (wave 26b, D12) the member's stall cut: -StallSec, else its entry's stall_sec, else 900
2909:            $slotStall = 900
2910:            if ($stallGiven) { $slotStall = $StallSec }
2911:            elseif ([int](Get-PropertyValue $pm.Entry 'StallSec' -1) -ge 0) { $slotStall = [int]$pm.Entry.StallSec }
2912:            $guard = Get-PanelMemberGuard -TimeoutSec $slotTimeout -ContinueSec $slotContinue -Repair:$repairEnabled -DenialRetry:([bool]((Get-EngineSpec $engineK).DenialRetry -and $DenialRetry -eq 1))
2913:            if ($guardHook -gt 0) { $guard = $guardHook }
2914:            $slot = [pscustomobject]@{
2915:                Pm = $pm; K = $k; N = ($panelNumbers.N + $k - 1); Nn = $nnK; Engine = $engineK
2916:                TimeoutSec = $slotTimeout; TimeoutSource = $slotTimeoutSource; ContinueSec = $slotContinue; StallSec = $slotStall; ExternalWaitShown = $false
2917:                ReplyName = "$ReplyName-$slug"; Reply = "handoffs/$nnK-$((Get-EngineSpec $engineK).Prefix)-$ReplyName-$slug.md"
2918:                RecordPath = (Get-MemberPendingPath -TaskDir $taskDir -Nn $nnK); ConsultId = [guid]::NewGuid().ToString()
2919:                Group = [int]$panelPlan.GroupOf[[int]$pm.Entry.Position]; Guard = $guard
2920:                State = 'waiting'; Proc = $null; Watch = $null; Exit = $null; Wall = 0; OutPath = ''; ErrPath = ''
2921:                Entry = $null; Refusal = ''; RecordState = ''; RecordKept = $false; NotStarted = ''; StartError = ''; Lines = [string[]]@()
2922:            }
2923:            $panelSlots.Add($slot)
2924:            $slotOf[[int]$pm.Entry.Position] = $slot
2925:        }
2926:        # (wave 26b, D13) the endpoint fingerprints of every endpoint group (the machine-wide count);
2927:        # (wave 29b, E16) and the plans of its members: a running row of the plan counts too
2928:        $panelGroupFps = @{}
2929:        $panelGroupPlans = @{}
2930:        foreach ($s in $panelSlots) {
2931:            $gi = [int]$s.Group
2932:            if (-not $panelGroupFps.ContainsKey($gi)) { $panelGroupFps[$gi] = [string[]]@() }
2933:            if (-not $panelGroupPlans.ContainsKey($gi)) { $panelGroupPlans[$gi] = [string[]]@() }
2934:            $fpS = [string]$s.Pm.Identity.Fingerprint
2935:            if ($fpS -and $panelGroupFps[$gi] -notcontains $fpS) { $panelGroupFps[$gi] = [string[]]@($panelGroupFps[$gi] + $fpS) }
2936:            $plS = [string](Get-PropertyValue $s.Pm.Entry 'Plan' '')
2937:            if ($plS -and $panelGroupPlans[$gi] -cnotcontains $plS) { $panelGroupPlans[$gi] = [string[]]@($panelGroupPlans[$gi] + $plS) }
2938:        }
2939:
2940:        # (wave 25, R12) -Detach: the panel's checks passed (D2: the launchers, the records, the
2941:        # stores, the selection) - the background runs it; this process writes the `starting`
2942:        # record and returns. The budget (D4) from the plan and the members' guards.
2943:        if ($detachForeground) {
2944:            $detachGuards = @{}
2945:            foreach ($s in $panelSlots) { $detachGuards[[int]$s.Pm.Entry.Position] = [int]$s.Guard }
2946:            $detachBudget = Get-DetachedBudget -Groups $panelPlan.Groups -GuardOf $detachGuards -Cap $PanelConcurrency
2947:            $detachMembers = @(foreach ($pm in @($panelEntries | Where-Object { $_.State -ne 'not-picked' })) {
2948:                    $detachShown = Format-ReviewerLineage -Provider $pm.Identity.Provider -Model $pm.Identity.Model -Engine ([string]$pm.Identity.Engine)
2949:                    if ($pm.State -eq 'run') { New-DetachedMember -Position ([int]$pm.Entry.Position) -Lineage $detachShown }
2950:                    else { New-DetachedMember -Position ([int]$pm.Entry.Position) -Lineage $detachShown -State 'skipped' -Outcome ([string]$pm.Reason) }
2951:                })
2952:            # D8: the brief and the artifacts absolute (a missing artifact is refused here, not by every member)
2953:            $detachArtifacts = @(Resolve-ArtifactPaths -Paths (Split-ArtifactArgument -Values $Artifact -Bases @($callerCwd, $repoRoot)) -Bases @($callerCwd, $repoRoot))
2954:            $detachBrief = ''
2955:            if ($Brief) { $detachBrief = (Resolve-Path -LiteralPath $briefProbe).Path }
2956:            $detachPlan = "a review panel of $($panelRunners.Count) of $($panelEntries.Count) roster entries, $($panelPlan.Text) (purpose $purposeLabel, timeout $TimeoutSec s per member)"
2957:            Start-DetachedRun -Kind 'panel' -Members $detachMembers -Budget $detachBudget -Plan $detachPlan -BriefFull $detachBrief -ArtifactFull @($detachArtifacts | ForEach-Object { $_.full }) -Warnings (@($rangeWarning) + @($panelWarnings) + @($panelCoordinatorWarnings))
2958:        }
2959:        # (wave 25) a detached panel: its members with their numbers, in roster order
2960:        if ($script:DetachRun) {
2961:            Set-DetachedMembers @(foreach ($pm in @($panelEntries | Where-Object { $_.State -ne 'not-picked' })) {
2962:                    $detachShown = Format-ReviewerLineage -Provider $pm.Identity.Provider -Model $pm.Identity.Model -Engine ([string]$pm.Identity.Engine)
2963:                    if ($pm.State -eq 'run') {
2964:                        $ds = $slotOf[[int]$pm.Entry.Position]
2965:                        New-DetachedMember -Position ([int]$pm.Entry.Position) -Lineage $detachShown -N $ds.N -Handoff $ds.Nn -Reply $ds.Reply
2966:                    } else { New-DetachedMember -Position ([int]$pm.Entry.Position) -Lineage $detachShown -State 'skipped' -Outcome ([string]$pm.Reason) }
2967:                })
2968:        }
2969:
2970:        $panelVerb = if ($DryRun) { 'would run' } else { 'run' }
